// Package mcpidentity signs the identity tokens the platform's MCP gateway
// sends MCP servers (docs/mcp-identity.md): short-lived ES256 JWTs saying
// which agent calls, for which team, in what kind of thread and, when the
// platform's records say so, for which person. It keeps the signing keys
// (generated by the platform, sealed with ENCRYPTION_KEY, rotated with a
// published-before-use overlap) and serves their public halves as a JWKS.
//
// Who a call is for is decided by internal/mcp from the platform's own
// records; this package only signs what it is given and never logs a token
// or a key.
package mcpidentity

import (
	"context"
	"crypto"
	"crypto/ecdsa"
	"crypto/elliptic"
	"crypto/rand"
	"crypto/x509"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"sort"
	"sync"
	"time"

	"github.com/go-jose/go-jose/v4"
	"github.com/go-jose/go-jose/v4/jwt"
	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/ncecere/pi-durable-platform/internal/audit"
	"github.com/ncecere/pi-durable-platform/internal/secrets"
	"github.com/ncecere/pi-durable-platform/internal/store"
	"github.com/ncecere/pi-durable-platform/internal/store/dbgen"
)

const (
	// Header carries the token to the MCP server (Open MCP Portal's name),
	// always the bare token.
	Header = "MCP-Gateway-Identity"
	// ThreadHeader is how the runtime tells the gateway which of its
	// agent's threads a call belongs to. It never reaches the server.
	ThreadHeader = "PDP-Thread"
	// JWKSPath serves the public keys on the platform's web listener.
	JWKSPath = "/.well-known/mcp-identity-jwks.json"
	// PrincipalType is the token's principal_type: the caller is an agent.
	PrincipalType = "agent"

	// TokenTTL is a token's life; it is valid from NotBeforeSkew before it
	// was issued.
	TokenTTL      = 5 * time.Minute
	NotBeforeSkew = 30 * time.Second
	// RetiredPublished is how long a key stays in the JWKS after a newer
	// one began signing (much longer than a token lives).
	RetiredPublished = time.Hour
	// RetiredDeleteAfter: a rotation deletes keys that stopped signing
	// longer ago than this.
	RetiredDeleteAfter = 24 * time.Hour
	// DefaultPrepublish is how long a rotated key is published before it
	// signs; MinPrepublish the least a rotation accepts (servers cache the
	// JWKS for up to JWKSMaxAge).
	DefaultPrepublish = 24 * time.Hour
	MinPrepublish     = 10 * time.Minute
	// JWKSMaxAge is the JWKS's Cache-Control max-age.
	JWKSMaxAge = 5 * time.Minute
	// MaxKeyAge: doctor warns when the signing key is older.
	MaxKeyAge = 90 * 24 * time.Hour

	// cacheTTL bounds how long a replica keeps the key list: a rotation
	// made elsewhere is seen within it.
	cacheTTL = time.Minute
	lockKey  = "pdp.mcp-identity-key"
)

// Audit actions (target type platform, target mcp_identity_key).
const (
	AuditCreate = "platform.mcp_identity_key_create"
	AuditRotate = "platform.mcp_identity_key_rotate"
	auditTarget = "mcp_identity_key"
)

// ErrNoKey: no key can sign now.
var ErrNoKey = errors.New("mcp identity: no signing key")

// Team is the calling agent's team.
type Team struct {
	ID   uuid.UUID `json:"id"`
	Slug string    `json:"slug"`
	// Kind is team, or personal for a personal workspace.
	Kind string `json:"kind"`
}

// Person is who the call is for, by their OIDC identity.
type Person struct {
	Issuer  string `json:"iss"`
	Subject string `json:"sub"`
	// Email only when the server receives it.
	Email string `json:"email,omitempty"`
}

// Claims are what a token says beyond iss, aud, sub and the times.
type Claims struct {
	Agent     uuid.UUID
	AgentName string
	Team      Team
	// ThreadVisibility is private, shared or none.
	ThreadVisibility string
	// Person is nil when nobody is named.
	Person        *Person
	PersonPresent bool
	// Tool is the server's name of the tool called ("" when the request
	// isn't one tools/call).
	Tool string
}

// private are the token's own claims, as serialized.
type private struct {
	PrincipalType    string  `json:"principal_type"`
	Name             string  `json:"name"`
	Team             Team    `json:"team"`
	ThreadVisibility string  `json:"thread_visibility"`
	Person           *Person `json:"person,omitempty"`
	PersonPresent    bool    `json:"person_present"`
	Tool             string  `json:"tool,omitempty"`
}

// key is one stored key, opened.
type key struct {
	id        uuid.UUID
	kid       string
	signsFrom time.Time
	public    jose.JSONWebKey
	signer    jose.Signer // nil when the private key couldn't be opened
	openErr   error
}

// Keys signs tokens with the platform's keys and publishes them.
type Keys struct {
	pool   *pgxpool.Pool
	q      *dbgen.Queries
	box    *secrets.Box
	issuer string
	// Now is the clock (tests).
	Now func() time.Time

	mu       sync.Mutex
	cached   []key
	cachedAt time.Time
}

// New returns the keys of the platform whose URL (APP_URL) is issuer.
func New(pool *pgxpool.Pool, box *secrets.Box, issuer string) *Keys {
	return &Keys{pool: pool, q: dbgen.New(pool), box: box, issuer: issuer, Now: time.Now}
}

// Issuer is the tokens' iss.
func (k *Keys) Issuer() string { return k.issuer }

func keyAD(id uuid.UUID) []byte { return []byte("mcp_identity_key:" + id.String()) }

// Invalidate drops the cached key list (after a rotation in this process).
func (k *Keys) Invalidate() {
	k.mu.Lock()
	k.cached, k.cachedAt = nil, time.Time{}
	k.mu.Unlock()
}

// load returns the stored keys, oldest first, from a cache of up to cacheTTL.
func (k *Keys) load(ctx context.Context) ([]key, error) {
	k.mu.Lock()
	defer k.mu.Unlock()
	if len(k.cached) > 0 && k.Now().Sub(k.cachedAt) < cacheTTL {
		return k.cached, nil
	}
	rows, err := k.q.ListMCPIdentityKeys(ctx)
	if err != nil {
		return nil, err
	}
	out := make([]key, 0, len(rows))
	for _, r := range rows {
		kk := key{id: r.ID, kid: r.Kid, signsFrom: r.SignsFrom}
		if err := json.Unmarshal(r.PublicJwk, &kk.public); err != nil {
			return nil, fmt.Errorf("mcp identity key %s: public key: %w", r.ID, err)
		}
		kk.signer, kk.openErr = k.openSigner(r)
		out = append(out, kk)
	}
	// No key yet is not kept: another replica may make the first one any
	// moment, and the JWKS must show it at once.
	if len(out) > 0 {
		k.cached, k.cachedAt = out, k.Now()
	}
	return out, nil
}

func (k *Keys) openSigner(r dbgen.McpIdentityKey) (jose.Signer, error) {
	der, err := k.box.Open(r.PrivateKeyEnc, keyAD(r.ID))
	if err != nil {
		return nil, fmt.Errorf("mcp identity key %s can't be opened with ENCRYPTION_KEY: %w", r.ID, err)
	}
	parsed, err := x509.ParsePKCS8PrivateKey(der)
	if err != nil {
		return nil, fmt.Errorf("mcp identity key %s: %w", r.ID, err)
	}
	priv, ok := parsed.(*ecdsa.PrivateKey)
	if !ok || priv.Curve != elliptic.P256() {
		return nil, fmt.Errorf("mcp identity key %s is not a P-256 key", r.ID)
	}
	return jose.NewSigner(jose.SigningKey{Algorithm: jose.ES256, Key: jose.JSONWebKey{Key: priv, KeyID: r.Kid, Algorithm: string(jose.ES256)}},
		(&jose.SignerOptions{}).WithType("JWT"))
}

// current is the key that signs at now: the latest whose signs_from passed.
func current(keys []key, now time.Time) (key, bool) {
	var cur key
	found := false
	for _, kk := range keys {
		if !kk.signsFrom.After(now) && (!found || !kk.signsFrom.Before(cur.signsFrom)) {
			cur, found = kk, true
		}
	}
	return cur, found
}

// published are the keys the JWKS lists at now: the one that signs, the ones
// that will, and the ones that stopped less than RetiredPublished ago.
func published(keys []key, now time.Time) []key {
	sorted := append([]key(nil), keys...)
	sort.SliceStable(sorted, func(i, j int) bool { return sorted[i].signsFrom.Before(sorted[j].signsFrom) })
	var out []key
	for i, kk := range sorted {
		// It stopped when the first later key began signing (if that passed).
		stopped := false
		var stoppedAt time.Time
		for _, n := range sorted[i+1:] {
			if n.signsFrom.After(kk.signsFrom) && !n.signsFrom.After(now) {
				stopped, stoppedAt = true, n.signsFrom
				break
			}
		}
		if stopped && now.Sub(stoppedAt) > RetiredPublished {
			continue
		}
		out = append(out, kk)
	}
	return out
}

// Sign returns a token for audience aud saying c. The first key is created
// when there is none.
func (k *Keys) Sign(ctx context.Context, aud string, c Claims) (string, error) {
	keys, err := k.load(ctx)
	if err != nil {
		return "", err
	}
	now := k.Now()
	cur, ok := current(keys, now)
	if !ok && len(keys) == 0 {
		if _, err := k.Ensure(ctx); err != nil {
			return "", err
		}
		if keys, err = k.load(ctx); err != nil {
			return "", err
		}
		now = k.Now() // the new key signs from when it was made
		cur, ok = current(keys, now)
	}
	if !ok {
		return "", ErrNoKey
	}
	if cur.signer == nil {
		return "", cur.openErr
	}
	jti := make([]byte, 16)
	if _, err := rand.Read(jti); err != nil {
		return "", err
	}
	std := jwt.Claims{Issuer: k.issuer, Subject: c.Agent.String(), Audience: jwt.Audience{aud},
		ID: base64.RawURLEncoding.EncodeToString(jti), IssuedAt: jwt.NewNumericDate(now),
		NotBefore: jwt.NewNumericDate(now.Add(-NotBeforeSkew)), Expiry: jwt.NewNumericDate(now.Add(TokenTTL))}
	own := private{PrincipalType: PrincipalType, Name: c.AgentName, Team: c.Team, ThreadVisibility: c.ThreadVisibility,
		Person: c.Person, PersonPresent: c.PersonPresent, Tool: c.Tool}
	return jwt.Signed(cur.signer).Claims(std).Claims(own).Serialize()
}

// JWKS is the public key set servers verify tokens with.
func (k *Keys) JWKS(ctx context.Context) (jose.JSONWebKeySet, error) {
	keys, err := k.load(ctx)
	if err != nil {
		return jose.JSONWebKeySet{}, err
	}
	set := jose.JSONWebKeySet{Keys: []jose.JSONWebKey{}}
	for _, kk := range published(keys, k.Now()) {
		set.Keys = append(set.Keys, kk.public)
	}
	return set, nil
}

// ServeJWKS serves the JWKS: unauthenticated, cacheable for JWKSMaxAge.
func (k *Keys) ServeJWKS(w http.ResponseWriter, r *http.Request) {
	set, err := k.JWKS(r.Context())
	if err != nil {
		w.Header().Set("Cache-Control", "no-store")
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusServiceUnavailable)
		_ = json.NewEncoder(w).Encode(map[string]any{"error": map[string]string{"code": "unavailable", "message": "The keys can't be read now"}})
		return
	}
	w.Header().Set("Content-Type", "application/jwk-set+json")
	w.Header().Set("Cache-Control", fmt.Sprintf("public, max-age=%d", int(JWKSMaxAge.Seconds())))
	_ = json.NewEncoder(w).Encode(set)
}

// generate makes a P-256 key: its sealed private half and its public JWK.
func (k *Keys) generate(id uuid.UUID) (kid string, sealed, public []byte, err error) {
	priv, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		return "", nil, nil, err
	}
	jwk := jose.JSONWebKey{Key: &priv.PublicKey, Algorithm: string(jose.ES256), Use: "sig"}
	thumb, err := jwk.Thumbprint(crypto.SHA256)
	if err != nil {
		return "", nil, nil, err
	}
	jwk.KeyID = base64.RawURLEncoding.EncodeToString(thumb)
	if public, err = json.Marshal(jwk); err != nil {
		return "", nil, nil, err
	}
	der, err := x509.MarshalPKCS8PrivateKey(priv)
	if err != nil {
		return "", nil, nil, err
	}
	if sealed, err = k.box.Seal(der, keyAD(id)); err != nil {
		return "", nil, nil, err
	}
	return jwk.KeyID, sealed, public, nil
}

func lock(ctx context.Context, tx pgx.Tx) error {
	_, err := tx.Exec(ctx, "SELECT pg_advisory_xact_lock(hashtext($1))", lockKey)
	return err
}

// Ensure creates the first key, signing at once, when there is none (at
// serve's start, and the first time a token is needed). Replicas make one
// key between them. It reports whether it created one.
func (k *Keys) Ensure(ctx context.Context) (bool, error) {
	created := false
	err := store.InTx(ctx, k.pool, func(q *dbgen.Queries, tx pgx.Tx) error {
		if err := lock(ctx, tx); err != nil {
			return err
		}
		n, err := q.CountMCPIdentityKeys(ctx)
		if err != nil || n > 0 {
			return err
		}
		id := uuid.New()
		kid, sealed, public, err := k.generate(id)
		if err != nil {
			return err
		}
		now := k.Now()
		if _, err := q.InsertMCPIdentityKey(ctx, dbgen.InsertMCPIdentityKeyParams{ID: id, Kid: kid, PrivateKeyEnc: sealed, PublicJwk: public, SignsFrom: now}); err != nil {
			return err
		}
		created = true
		return audit.Record(ctx, q, audit.Entry{ActorKind: audit.ActorSystem, Action: AuditCreate, TargetType: "platform", TargetID: auditTarget,
			Metadata: map[string]any{"kid": kid, "signsFrom": now.UTC().Format(time.RFC3339)}})
	})
	if created {
		k.Invalidate()
	}
	return created, err
}

// RotateOptions choose how a new key takes over.
type RotateOptions struct {
	// Prepublish is how long the new key is published before it signs
	// (DefaultPrepublish when 0; at least MinPrepublish). Ignored with Now.
	Prepublish time.Duration
	// Now: the new key signs at once.
	Now bool
	// DropPrevious removes every other key at once (with Now: a leaked key).
	DropPrevious bool
}

// Rotation is what a rotation did.
type Rotation struct {
	Kid       string
	SignsFrom time.Time
	// Deleted keys: the previous ones (DropPrevious), or the ones retired
	// longer than RetiredDeleteAfter ago.
	Deleted int64
}

// Rotate adds a new key (audited). Without Now it signs after Prepublish,
// so servers' cached key sets already hold it; the previous key stays
// published for RetiredPublished after it stops.
func (k *Keys) Rotate(ctx context.Context, opts RotateOptions) (Rotation, error) {
	if opts.DropPrevious && !opts.Now {
		return Rotation{}, errors.New("dropping the previous keys needs the new key to sign now (--now)")
	}
	wait := opts.Prepublish
	if wait == 0 {
		wait = DefaultPrepublish
	}
	if opts.Now {
		wait = 0
	} else if wait < MinPrepublish {
		return Rotation{}, fmt.Errorf("the new key must be published at least %s before it signs", MinPrepublish)
	}
	var out Rotation
	err := store.InTx(ctx, k.pool, func(q *dbgen.Queries, tx pgx.Tx) error {
		if err := lock(ctx, tx); err != nil {
			return err
		}
		id := uuid.New()
		kid, sealed, public, err := k.generate(id)
		if err != nil {
			return err
		}
		now := k.Now()
		out = Rotation{Kid: kid, SignsFrom: now.Add(wait)}
		if _, err := q.InsertMCPIdentityKey(ctx, dbgen.InsertMCPIdentityKeyParams{ID: id, Kid: kid, PrivateKeyEnc: sealed, PublicJwk: public,
			SignsFrom: out.SignsFrom}); err != nil {
			return err
		}
		if opts.DropPrevious {
			out.Deleted, err = q.DeleteMCPIdentityKeysExcept(ctx, id)
		} else {
			out.Deleted, err = q.DeleteRetiredMCPIdentityKeys(ctx, now.Add(-RetiredDeleteAfter))
		}
		if err != nil {
			return err
		}
		return audit.Record(ctx, q, audit.Entry{ActorKind: audit.ActorSystem, Action: AuditRotate, TargetType: "platform", TargetID: auditTarget,
			Metadata: map[string]any{"kid": kid, "signsFrom": out.SignsFrom.UTC().Format(time.RFC3339), "immediate": opts.Now,
				"droppedPrevious": opts.DropPrevious, "deleted": out.Deleted}})
	})
	k.Invalidate()
	return out, err
}

// KeyInfo describes a stored key (no key material).
type KeyInfo struct {
	Kid       string
	SignsFrom time.Time
}

// Status is what doctor reports: the key that signs now (nil: none), the
// keys waiting to sign, and how many are stored.
type Status struct {
	Signing  *KeyInfo
	Upcoming []KeyInfo
	Total    int
}

// Inspect reads the stored keys without opening them.
func Inspect(ctx context.Context, q *dbgen.Queries, now time.Time) (Status, error) {
	rows, err := q.ListMCPIdentityKeys(ctx)
	if err != nil {
		return Status{}, err
	}
	keys := make([]key, len(rows))
	for i, r := range rows {
		keys[i] = key{id: r.ID, kid: r.Kid, signsFrom: r.SignsFrom}
	}
	st := Status{Total: len(rows)}
	if cur, ok := current(keys, now); ok {
		st.Signing = &KeyInfo{Kid: cur.kid, SignsFrom: cur.signsFrom}
	}
	for _, kk := range keys {
		if kk.signsFrom.After(now) {
			st.Upcoming = append(st.Upcoming, KeyInfo{Kid: kk.kid, SignsFrom: kk.signsFrom})
		}
	}
	return st, nil
}
